```c
#include <stdio.h>

int main(void) {
    int e1, e2, e3, x;

    if (scanf("%d%d%d%d", &e1, &e2, &e3, &x) != 4) {
        return 0;
    }

    printf("%d\n", (e2 - e1 <= x) ? e2 : e3);
    return 0;
}
```

